const s=new WeakMap,p=n=>n.kind==="tube"?n.ceil+1.65:2.6;function f(n){let i=s.get(n);if(i)return i;const r=n.frames.filter(t=>t.kind==="track"||t.kind==="tube"||t.kind==="spinner").map(t=>[t.p[2],t.p[1]+p(t)]).sort((t,o)=>t[0]-o[0]);return i={z:Float64Array.from(r,t=>t[0]),top:Float64Array.from(r,t=>t[1])},s.set(n,i),i}export function axisTop(n,i,r){const{z:t,top:o}=f(n);let l=0,a=t.length;for(;l<a;){const e=l+a>>1;t[e]<i?l=e+1:a=e}let c=-1/0;for(let e=l;e<t.length&&t[e]<=r;e++)o[e]>c&&(c=o[e]);return c}
